/** The shapes of `ASSETS` values (lib/assets/manifest.ts, generated by scripts/assets/build.ts). */

export interface ImageVariant {
  src: string
  width: number
  height: number
  /** JPEG/PNG only where no re-encode beat the source's own bytes, which are then served as they are. */
  type: 'image/avif' | 'image/webp' | 'image/jpeg' | 'image/png'
}

/**
 * A still for `<picture>`: the source's size, and every variant by width, AVIF first. AVIF is all or
 * nothing (every width or none), so a browser on the AVIF `<source>` always finds its density; the
 * rest are the `<img>`'s own candidates.
 */
export interface ImageAsset {
  width: number
  height: number
  variants: readonly ImageVariant[]
}

export interface VideoSource {
  src: string
  type: string
}

/** `sources` are in selection order: the browser takes the first it can play. */
export interface VideoAsset {
  width: number
  height: number
  sources: readonly VideoSource[]
}

/** A GL texture: AVIF when one passed parity at fewer bytes than the WebP, which is always there. */
export interface TextureAsset {
  avif?: string
  webp: string
  width: number
  height: number
}
